// Clock
 function updateClock() {
 const now = new Date();
 const hours = String(now.getHours()).padStart(2, '0');
 const minutes = String(now.getMinutes()).padStart(2, '0');
 document.getElementById('clock').textContent = `${hours}:${minutes}`;
 }

 function updateLockscreenClock() {
 const now = new Date();
 const hours = String(now.getHours()).padStart(2, '0');
 const minutes = String(now.getMinutes()).padStart(2, '0');
 document.getElementById('lockscreenTime').textContent = `${hours}:${minutes}`;
 
 const dateStr = now.toLocaleDateString('en-US', { 
 weekday: 'long', 
 month: 'long', 
 day: 'numeric' 
 });
 document.getElementById('lockscreenDate').textContent = dateStr;
 }

 updateClock();
 updateLockscreenClock();
 setInterval(updateClock, 1000);
 setInterval(updateLockscreenClock, 1000);

 // Lockscreen
 document.getElementById('lockscreen').addEventListener('click', function() {
 this.classList.add('hidden');
 showLoadingScreen();
 });

 // Start Menu
 function toggleStartMenu() {
 document.getElementById('startMenu').classList.toggle('active');
 }

 document.addEventListener('click', function(e) {
 const menu = document.getElementById('startMenu');
 const startButton = document.querySelector('.start-button');
 if (!menu.contains(e.target) && !startButton.contains(e.target)) {
 menu.classList.remove('active');
 }
 });

 // Shutdown
 function shutdown() {
 const lockscreen = document.getElementById('lockscreen');
 lockscreen.querySelector('.lockscreen-icon').innerHTML = '<img src="data:image/png;base64," style="width: 100%; height: 100%; object-fit: contain; image-rendering: pixelated;">';
 lockscreen.querySelector('.lockscreen-time').textContent = 'Shutting down...';
 lockscreen.querySelector('.lockscreen-date').textContent = '';
 lockscreen.querySelector('.lockscreen-prompt').textContent = 'Please wait...';
 lockscreen.classList.remove('hidden');
 
 setTimeout(() => {
 lockscreen.querySelector('.lockscreen-icon').innerHTML = '<img src="data:image/png;base64," style="width: 100%; height: 100%; object-fit: contain; image-rendering: pixelated;">';
 updateLockscreenClock();
 lockscreen.querySelector('.lockscreen-prompt').textContent = 'Click anywhere to continue...';
 }, 2000);
 }

 // Window management
 let draggedWindow = null;
 let offsetX = 0;
 let offsetY = 0;

 function openWindow(windowId) {
            if (windowId === 'music') {
                setTimeout(function() {
                    if (typeof window.generateMusicPlaylist === 'function') {
                        window.generateMusicPlaylist();
                    }
                }, 200);
            }
            
 document.getElementById(windowId).classList.add('active');
 bringToFront(windowId);
 document.getElementById('startMenu').classList.remove('active');
 
 // Initialize snail game canvas when game window opens
 if (windowId === 'snailGame') {
 setTimeout(initSnailCanvas, 100);
 }
 }

 function closeWindow(windowId) {
 document.getElementById(windowId).classList.remove('active');
 }

 function minimizeWindow(windowId) {
 const window = document.getElementById(windowId);
 window.classList.remove('active');
 
 // Add to taskbar if not already there
 addToTaskbar(windowId);
 }

 function maximizeWindow(windowId) {
 const window = document.getElementById(windowId);
 window.classList.toggle('maximized');
 }

 function addToTaskbar(windowId) {
 const taskbarButtons = document.getElementById('taskbarButtons');
 
 // Check if button already exists
 if (document.getElementById('taskbar-' + windowId)) return;
 
 const window = document.getElementById(windowId);
 const title = window.querySelector('.window-title').textContent.trim();
 const icon = window.querySelector('.window-title img');
 
 const button = document.createElement('div');
 button.className = 'taskbar-button';
 button.id = 'taskbar-' + windowId;
 button.onclick = () => restoreWindow(windowId);
 
 if (icon) {
 button.innerHTML = `<img src="${icon.src}"><span>${title}</span>`;
 } else {
 button.innerHTML = `<span>${title}</span>`;
 }
 
 taskbarButtons.appendChild(button);
 }

 function restoreWindow(windowId) {
 const window = document.getElementById(windowId);
 window.classList.add('active');
 window.classList.remove('maximized');
 bringToFront(windowId);
 
 // Remove from taskbar
 const taskbarButton = document.getElementById('taskbar-' + windowId);
 if (taskbarButton) taskbarButton.remove();
 }

 function bringToFront(windowId) {
 const windows = document.querySelectorAll('.window');
 windows.forEach(w => w.style.zIndex = 1000);
 document.getElementById(windowId).style.zIndex = 1001;
 }

 function startDrag(e, windowId) {
 if (e.target.closest('.window-button') || e.target.closest('.window-resizer')) return;
 draggedWindow = document.getElementById(windowId);
 const rect = draggedWindow.getBoundingClientRect();
 offsetX = e.clientX - rect.left;
 offsetY = e.clientY - rect.top;
 bringToFront(windowId);
 }

 document.addEventListener('mousemove', (e) => {
 if (draggedWindow) {
 const x = e.clientX - offsetX;
 const y = e.clientY - offsetY;
 draggedWindow.style.left = Math.max(0, Math.min(x, window.innerWidth - draggedWindow.offsetWidth)) + 'px';
 draggedWindow.style.top = Math.max(0, Math.min(y, window.innerHeight - draggedWindow.offsetHeight - 40)) + 'px';
 }
 });

 document.addEventListener('mouseup', () => {
 draggedWindow = null;
 });

 // Guestbook
 function addGuestbookEntry() {
 const nameInput = document.getElementById('guestName');
 const messageInput = document.getElementById('guestMessage');
 const name = nameInput.value.trim();
 const message = messageInput.value.trim();
 const errorContainer = document.getElementById('guestbookError');

 // Reset states
 nameInput.style.border = '';
 nameInput.removeAttribute('aria-invalid');
 messageInput.style.border = '';
 messageInput.removeAttribute('aria-invalid');
 if (errorContainer) {
 errorContainer.style.display = 'none';
 errorContainer.textContent = '';
 }

 if (!name || !message) {
 if (errorContainer) {
 errorContainer.textContent = 'please fill in both fields!';
 errorContainer.style.display = 'block';
 }
 if (!name) {
 nameInput.style.border = '2px solid #c04040';
 nameInput.setAttribute('aria-invalid', 'true');
 }
 if (!message) {
 messageInput.style.border = '2px solid #c04040';
 messageInput.setAttribute('aria-invalid', 'true');
 }
 return;
 }

 const entry = document.createElement('div');
 entry.className = 'guestbook-entry';
 
 const now = new Date();
 const dateStr = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

 entry.innerHTML = `
 <div class="entry-name">${escapeHtml(name)}</div>
 <div class="entry-date">${dateStr}</div>
 <div class="entry-message">${escapeHtml(message)}</div>
 `;

 document.getElementById('guestbookEntries').insertBefore(entry, document.getElementById('guestbookEntries').firstChild);

 saveGuestbookEntry(name, message, dateStr);

 document.getElementById('guestName').value = '';
 document.getElementById('guestMessage').value = '';
 }

 function escapeHtml(text) {
 const div = document.createElement('div');
 div.textContent = text;
 return div.innerHTML;
 }

 function saveGuestbookEntry(name, message, date) {
 let entries = JSON.parse(localStorage.getItem('guestbookEntries') || '[]');
 entries.unshift({ name, message, date });
 localStorage.setItem('guestbookEntries', JSON.stringify(entries));
 }

 function loadGuestbookEntries() {
 const entries = JSON.parse(localStorage.getItem('guestbookEntries') || '[]');
 const container = document.getElementById('guestbookEntries');
 
 entries.forEach(entry => {
 const entryDiv = document.createElement('div');
 entryDiv.className = 'guestbook-entry';
 entryDiv.innerHTML = `
 <div class="entry-name">${escapeHtml(entry.name)}</div>
 <div class="entry-date">${entry.date}</div>
 <div class="entry-message">${escapeHtml(entry.message)}</div>
 `;
 container.appendChild(entryDiv);
 });
 }

