 // Paint program
 const canvas = document.getElementById('paintCanvas');
 const ctx = canvas.getContext('2d');
 let painting = false;
 let currentTool = 'draw';
 let currentColor = '#000000';
 let brushSize = 5;

 function setTool(tool) {
 currentTool = tool;
 document.querySelectorAll('.paint-tool').forEach(t => t.classList.remove('active'));
 event.target.classList.add('active');
 }

 function setColor(color) {
 currentColor = color;
 document.querySelectorAll('.color-option').forEach(c => c.classList.remove('active'));
 event.target.classList.add('active');
 // Update color wheel to match
 document.getElementById('colorWheel').value = color;
 }

 function setColorFromWheel() {
 const wheel = document.getElementById('colorWheel');
 currentColor = wheel.value;
 // Remove active from all preset colors
 document.querySelectorAll('.color-option').forEach(c => c.classList.remove('active'));
 }

 function changeBrushSize() {
 const select = document.getElementById('brushSize');
 brushSize = parseInt(select.value);
 }

 function clearCanvas() {
 ctx.clearRect(0, 0, canvas.width, canvas.height);
 }

 canvas.addEventListener('mousedown', startPaint);
 canvas.addEventListener('mouseup', endPaint);
 canvas.addEventListener('mousemove', paint);

 function startPaint(e) {
 painting = true;
 paint(e);
 }

 function endPaint() {
 painting = false;
 ctx.beginPath();
 }

 function paint(e) {
 if (!painting) return;

 const rect = canvas.getBoundingClientRect();
 const x = e.clientX - rect.left;
 const y = e.clientY - rect.top;

 ctx.lineWidth = currentTool === 'erase' ? 20 : brushSize;
 ctx.lineCap = 'round';
 ctx.strokeStyle = currentTool === 'erase' ? '#ffffff' : currentColor;

 ctx.lineTo(x, y);
 ctx.stroke();
 ctx.beginPath();
 ctx.moveTo(x, y);
 }

