 // Snail Game
 let snailCanvas, snailCtx;
 const gridSize = 20;
 const tileCount = 20;
 
 let snail = [];
 let snailLength = 3;
 let food = {x: 15, y: 15};
 let dx = 0;
 let dy = 0;
 let score = 0;
 let highScore = localStorage.getItem('snailHighScore') || 0;
 let gameLoop;
 let gameRunning = false;
 let gamePaused = false;

 // Initialize canvas when game window is opened
 function initSnailCanvas() {
 snailCanvas = document.getElementById('snailCanvas');
 if (snailCanvas) {
 snailCtx = snailCanvas.getContext('2d');
 
 // Show initial screen
 snailCtx.fillStyle = '#0f1419';
 snailCtx.fillRect(0, 0, snailCanvas.width, snailCanvas.height);
 
 snailCtx.fillStyle = '#89f7fe';
 snailCtx.font = '20px "Segoe UI"';
 snailCtx.textAlign = 'center';
 snailCtx.fillText('Press Start Game to begin!', snailCanvas.width/2, snailCanvas.height/2);
 
 // Update high score display
 const highScoreEl = document.getElementById('highScore');
 if (highScoreEl) {
 highScoreEl.textContent = highScore;
 }
 }
 }

 function initSnailGame() {
 if (!snailCanvas) initSnailCanvas();
 
 snail = [{x: 10, y: 10}];
 snailLength = 3;
 dx = 1; // Start moving right
 dy = 0;
 score = 0;
 gamePaused = false;
 
 const scoreEl = document.getElementById('gameScore');
 if (scoreEl) scoreEl.textContent = score;
 
 const gameOverScreen = document.getElementById('gameOverScreen');
 if (gameOverScreen) gameOverScreen.classList.remove('show');
 
 placeFood();
 }

 function startSnailGame() {
 if (!snailCanvas) initSnailCanvas();
 
 if (gameRunning && !gamePaused) {
 // If already running, restart
 clearInterval(gameLoop);
 }
 
 initSnailGame();
 gameRunning = true;
 gamePaused = false;
 
 if (gameLoop) clearInterval(gameLoop);
 gameLoop = setInterval(updateSnailGame, 150);
 }

 function pauseSnailGame() {
 if (!gameRunning) return;
 gamePaused = !gamePaused;
 
 if (gamePaused && snailCtx) {
 snailCtx.fillStyle = 'rgba(0, 0, 0, 0.7)';
 snailCtx.fillRect(0, 0, snailCanvas.width, snailCanvas.height);
 
 snailCtx.fillStyle = '#89f7fe';
 snailCtx.font = '24px "Segoe UI"';
 snailCtx.textAlign = 'center';
 snailCtx.fillText('PAUSED', snailCanvas.width/2, snailCanvas.height/2);
 }
 }

 function placeFood() {
 food.x = Math.floor(Math.random() * tileCount);
 food.y = Math.floor(Math.random() * tileCount);
 
 // Make sure food doesn't spawn on snail
 for (let segment of snail) {
 if (segment.x === food.x && segment.y === food.y) {
 placeFood();
 return;
 }
 }
 }

 function updateSnailGame() {
 if (gamePaused || !gameRunning || !snailCtx) return;

 // Move snail
 const head = {x: snail[0].x + dx, y: snail[0].y + dy};
 
 // Check wall collision
 if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount) {
 gameOver();
 return;
 }
 
 // Check self collision
 for (let segment of snail) {
 if (segment.x === head.x && segment.y === head.y) {
 gameOver();
 return;
 }
 }
 
 snail.unshift(head);
 
 // Check food collision
 if (head.x === food.x && head.y === food.y) {
 score++;
 snailLength++;
 const scoreEl = document.getElementById('gameScore');
 if (scoreEl) scoreEl.textContent = score;
 placeFood();
 } else {
 while (snail.length > snailLength) {
 snail.pop();
 }
 }
 
 drawSnailGame();
 }

 function drawSnailGame() {
 if (!snailCtx) return;
 
 // Clear canvas
 snailCtx.fillStyle = '#0f1419';
 snailCtx.fillRect(0, 0, snailCanvas.width, snailCanvas.height);
 
 // Draw grid
 snailCtx.strokeStyle = 'rgba(80, 144, 192, 0.1)';
 snailCtx.lineWidth = 1;
 for (let i = 0; i <= tileCount; i++) {
 snailCtx.beginPath();
 snailCtx.moveTo(i * gridSize, 0);
 snailCtx.lineTo(i * gridSize, snailCanvas.height);
 snailCtx.stroke();
 
 snailCtx.beginPath();
 snailCtx.moveTo(0, i * gridSize);
 snailCtx.lineTo(snailCanvas.width, i * gridSize);
 snailCtx.stroke();
 }
 
 // Draw snail (pink/blue gradient)
 snail.forEach((segment, index) => {
 const ratio = index / Math.max(snail.length - 1, 1);
 const r = Math.floor(255 * (1 - ratio) + 80 * ratio);
 const g = Math.floor(107 * (1 - ratio) + 144 * ratio);
 const b = Math.floor(157 * (1 - ratio) + 192 * ratio);
 
 snailCtx.fillStyle = `rgb(${r}, ${g}, ${b})`;
 snailCtx.fillRect(segment.x * gridSize + 2, segment.y * gridSize + 2, gridSize - 4, gridSize - 4);
 
 // Add shine effect on head
 if (index === 0) {
 snailCtx.fillStyle = 'rgba(255, 255, 255, 0.3)';
 snailCtx.fillRect(segment.x * gridSize + 4, segment.y * gridSize + 4, gridSize - 12, gridSize - 12);
 }
 });
 
 // Draw food (flower)
 snailCtx.fillStyle = '#89f7fe';
 snailCtx.beginPath();
 snailCtx.arc(food.x * gridSize + gridSize/2, food.y * gridSize + gridSize/2, gridSize/3, 0, Math.PI * 2);
 snailCtx.fill();
 
 // Flower center
 snailCtx.fillStyle = '#ffff00';
 snailCtx.beginPath();
 snailCtx.arc(food.x * gridSize + gridSize/2, food.y * gridSize + gridSize/2, gridSize/6, 0, Math.PI * 2);
 snailCtx.fill();
 }

 function gameOver() {
 gameRunning = false;
 clearInterval(gameLoop);
 
 const finalScoreEl = document.getElementById('finalScore');
 if (finalScoreEl) finalScoreEl.textContent = score;
 
 const gameOverScreen = document.getElementById('gameOverScreen');
 if (gameOverScreen) gameOverScreen.classList.add('show');
 
 if (score > highScore) {
 highScore = score;
 localStorage.setItem('snailHighScore', highScore);
 const highScoreEl = document.getElementById('highScore');
 if (highScoreEl) highScoreEl.textContent = highScore;
 }
 }

 // Keyboard controls
 document.addEventListener('keydown', (e) => {
 if (!gameRunning || gamePaused) return;
 
 switch(e.key) {
 case 'ArrowUp':
 if (dy !== 1) { dx = 0; dy = -1; }
 e.preventDefault();
 break;
 case 'ArrowDown':
 if (dy !== -1) { dx = 0; dy = 1; }
 e.preventDefault();
 break;
 case 'ArrowLeft':
 if (dx !== 1) { dx = -1; dy = 0; }
 e.preventDefault();
 break;
 case 'ArrowRight':
 if (dx !== -1) { dx = 1; dy = 0; }
 e.preventDefault();
 break;
 }
 });

 // Loading screen - shows AFTER lockscreen click
 let loadingInterval;
 
 function showLoadingScreen() {
 const loadingScreen = document.getElementById('loadingScreen');
 const percentage = document.getElementById('loadingPercentage');
 
 loadingScreen.classList.add('active');
 
 let progress = 0;
 loadingInterval = setInterval(() => {
 progress += Math.random() * 15 + 5;
 if (progress >= 100) {
 progress = 100;
 clearInterval(loadingInterval);
 percentage.textContent = '100%';
 
 setTimeout(() => {
 loadingScreen.classList.add('hidden');
 setTimeout(() => {
 loadingScreen.classList.remove('active');
 loadingScreen.classList.remove('hidden');
 }, 500);
 }, 500);
 } else {
 percentage.textContent = Math.floor(progress) + '%';
 }
 }, 100);
 }

        function handleSnailKey(key) {
            if (!snailGame.running) return;
            
            if (key === 'ArrowUp' && snailGame.direction !== 'down') {
                snailGame.direction = 'up';
            } else if (key === 'ArrowDown' && snailGame.direction !== 'up') {
                snailGame.direction = 'down';
            } else if (key === 'ArrowLeft' && snailGame.direction !== 'right') {
                snailGame.direction = 'left';
            } else if (key === 'ArrowRight' && snailGame.direction !== 'left') {
                snailGame.direction = 'right';
            }
        }
        
        // Show mobile controls on small screens
        function checkMobileControls() {
            const controls = document.querySelector('.mobile-game-controls');
            if (controls && window.innerWidth <= 768) {
                controls.style.display = 'block';
            } else if (controls) {
                controls.style.display = 'none';
            }
        }
        
        window.addEventListener('resize', checkMobileControls);

    
        
        // Music Player with Clickable Playlist
        var songs = [
            { title: "Fake Empire - The National", id: "YKYvAJBsoqY" },
            { title: "No Surprises - Radiohead", id: "LBt60dfwEBY" },
            { title: "Lazarus - David Bowie", id: "Piq-_MOcnRc" },
            { title: "Fear of God - Curta'n Wall", id: "8WDhlW3u93U" },
            { title: "Let Down - Radiohead", id: "ZVgHPSyEIqk" },
            { title: "Bless the Telephone - Labi Siffre", id: "gdpHAB7kZTU" },
            { title: "The Modern Leper - Frightened Rabbit", id: "OJNFwGdh4iE" },
            { title: "Between the Bars - Elliott Smith", id: "8aomt1gQ6So" }
        ];
        
        var currentMusicIndex = -1;
        
        window.playMusicSong = function(index) {
            if (index >= 0 && index < songs.length) {
                currentMusicIndex = index;
                var song = songs[index];
                
                var titleEl = document.getElementById('currentSongTitle');
                if (titleEl) {
                    titleEl.textContent = '♪ ' + song.title;
                }
                
                var player = document.getElementById('youtubePlayer');
                if (player) {
                    player.src = 'https://www.youtube.com/embed/' + song.id + '?autoplay=1';
                }
                
                updateMusicButtons();
            }
        };
        
        window.generateMusicPlaylist = function() {
            var container = document.getElementById('musicPlaylist');
            if (!container) return;
            
            container.innerHTML = '';
            for (var i = 0; i < songs.length; i++) {
                var btn = document.createElement('button');
                btn.className = 'music-playlist-btn';
                btn.textContent = (i + 1) + '. ' + songs[i].title;
                btn.setAttribute('data-song-index', i);
                btn.onclick = function() {
                    window.playMusicSong(parseInt(this.getAttribute('data-song-index')));
                };
                if (i === currentMusicIndex) {
                    btn.classList.add('active');
                }
                container.appendChild(btn);
            }
        };
        
        function updateMusicButtons() {
            var buttons = document.querySelectorAll('.music-playlist-btn');
            for (var i = 0; i < buttons.length; i++) {
                if (i === currentMusicIndex) {
                    buttons[i].classList.add('active');
                } else {
                    buttons[i].classList.remove('active');
                }
            }
        }